package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Signed callbacks persist immutable deltas. Package identities also deduplicate new message IDs. */
@Service
public class WmsOutboundReceiptService {
    @Resource private WmsStore db;
    @Resource private WmsOutboundReceiptNotifier notifier;
    @Resource private WmsConnections connections;
    @Resource private WmsInteractionLog logs;
    @Resource private List<WmsProtocol> protocols;
    private WmsProtocol protocol(String provider){return protocols.stream().filter(p->p.provider().equals(provider)).findFirst().orElseThrow(()->new IllegalArgumentException("不支持的仓库协议"));}
    public String callback(String company,String key,Map<String,String> params,String body){Map<String,Object> connection=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",company,key);WmsProtocol protocol=protocol(text(connection.get("provider")));long start=System.currentTimeMillis(),log=logs.start(company,id(connection.get("id")),null,"","IN","OUTBOUND_RECEIPT",body);try{WmsProtocol.OutboundReceipt receipt=protocol.outboundCallback(connection,connections.secret(connection),params,body);Map<String,Object> task=db.one("SELECT * FROM wms_outbound_task WHERE company_code=? AND connection_id=? AND shipment_sn=?",company,connection.get("id"),receipt.shipmentSn);db.jdbc.update("UPDATE wms_interaction_log SET task_id=?,ticket_sn=? WHERE id=?",task.get("id"),receipt.shipmentSn,log);try{accept(company,id(task.get("id")),receipt);}catch(WmsOutboundReceiptReviews.Conflict e){new WmsOutboundReceiptReviews(db,this).retain(company,id(task.get("id")),receipt,log,e);throw new IllegalArgumentException(e.getMessage()+"；已进入待人工核对，本次未扣账");}String reply=protocol.acknowledgement(true,"出库回传已接收，等待库存及订单记账");logs.finish(log,"SUCCESS",reply,"",System.currentTimeMillis()-start);return reply;}catch(Exception e){String message=e instanceof IllegalArgumentException?text(e.getMessage()):"出库回传处理失败，请重试";String reply=protocol.acknowledgement(false,message);logs.finish(log,"FAILED",reply,message,System.currentTimeMillis()-start);return reply;}}
    private long number(Map<String,Object> row,String key){return row.get(key)==null?0:id(row.get(key));}
    private String hash(Object value){return QimenProtocol.hash("SHA-256",db.encode(value)).toLowerCase(Locale.ROOT);}
    private Map<String,Object> packageFingerprint(WmsProtocol.OutboundPackage p){require(p.packageCode.matches("[A-Za-z0-9_.-]{1,100}")&&p.expressCode.matches("[A-Za-z0-9_-]{1,100}")&&!p.logisticsCode.trim().isEmpty()&&p.logisticsCode.length()<=128&&!p.logisticsCode.contains("\u0000"),"包裹编码、运单号或快递编码无效");require(!p.items.isEmpty()&&p.items.size()<=500,"包裹必须包含商品数量");Map<String,Long> items=new TreeMap<>();for(WmsProtocol.PackageItem i:p.items){require(!i.sku.isEmpty()&&i.sku.length()<=128&&i.quantity>0,"包裹商品或数量无效");items.merge(i.sku,i.quantity,Math::addExact);}return map("package_code",p.packageCode,"express_code",p.expressCode,"logistics_code",p.logisticsCode,"items",items);}
    public long accept(String company,long taskId,WmsProtocol.OutboundReceipt receipt){return acceptReviewed(company,taskId,receipt,0,Collections.emptyList());}
    @SuppressWarnings("unchecked") long acceptReviewed(String company,long taskId,WmsProtocol.OutboundReceipt receipt,long review,List<?> related){long accepted=db.tx().execute(s->{
        Map<String,Object> task=db.one("SELECT * FROM wms_outbound_task WHERE company_code=? AND id=? FOR UPDATE",company,taskId);if(receipt.owner.isEmpty()){Set<String> owners=new HashSet<>();for(WmsProtocol.OutboundLine line:receipt.lines)if(!line.owner.isEmpty())owners.add(line.owner);require(owners.size()<=1,"出库回传明细货主不一致");receipt.owner=owners.isEmpty()?text(task.get("external_owner")):owners.iterator().next();}if(receipt.externalOrder.isEmpty())receipt.externalOrder=text(task.get("external_order"));require(text(task.get("shipment_sn")).equals(receipt.shipmentSn)&&text(task.get("external_warehouse")).equals(receipt.warehouse)&&text(task.get("external_owner")).equals(receipt.owner),"回传发货单、仓库或货主与绑定不一致");require(receipt.messageId!=null&&!receipt.messageId.isEmpty()&&receipt.messageId.length()<=128,"出库回传缺少有效消息ID");require(receipt.externalOrder!=null&&!receipt.externalOrder.isEmpty()&&(text(task.get("external_order")).isEmpty()||text(task.get("external_order")).equals(receipt.externalOrder)),"回传仓库单号缺失或发生变化");String digest=hash(receipt);List<Map<String,Object>> previous=db.jdbc.queryForList("SELECT id,payload_hash FROM wms_outbound_receipt_event WHERE company_code=? AND task_id=? AND message_id=?",company,taskId,receipt.messageId);if(!previous.isEmpty()){require(digest.equals(previous.get(0).get("payload_hash")),"相同消息ID的出库内容发生变化");return id(previous.get(0).get("id"));}
        if("CONFIRMED".equals(text(task.get("cancel_state"))))throw new WmsOutboundReceiptReviews.Conflict("CANCEL_CONFLICT","仓库已确认取消后又回传出库，需人工核对实际出库与原占用");
        require(Arrays.asList("SENDING","UNKNOWN","ACCEPTED").contains(task.get("dispatch_state")),"发货单尚未有效下发或仓库已明确拒绝，需先核对受理结果");require(Arrays.asList("PARTDELIVERED","DELIVERED").contains(receipt.status),"不支持的出库回传状态");require(receipt.totalLines==null||receipt.totalLines==receipt.sourceLineCount,"出库报文尚未包含完整明细");require(receipt.lines.size()<=500&&receipt.packages.size()<=100,"出库报文明细或包裹数量超过限制");
        Map<String,Object> original;try{original=db.json.readValue(text(task.get("payload_json")),Map.class);}catch(Exception e){throw new IllegalArgumentException("原下发快照损坏");}Map<Long,Map<String,Object>> planned=new TreeMap<>();for(Map<String,Object> line:(List<Map<String,Object>>)original.get("lines"))planned.put(id(line.get("id")),line);Map<Long,Long> reported=new TreeMap<>();Map<String,Long> lineTotals=new TreeMap<>();
        for(WmsProtocol.OutboundLine line:receipt.lines){require(line.quantity>=0&&line.owner.equals(receipt.owner),"回传明细货主或数量无效");List<Map<String,Object>> matches=new ArrayList<>();for(Map<String,Object> plan:planned.values())if(text(plan.get("sku_sn")).equals(line.sku)&&(line.lineNo.isEmpty()||text(plan.get("id")).equals(line.lineNo))&&(line.batch.isEmpty()||text(plan.get("batch_code")).equals(line.batch)))matches.add(plan);require(matches.size()==1,"回传商品、行号或批次无法唯一匹配原占用来源");if(line.quantity==0)continue;Map<String,Object> plan=matches.get(0);reported.merge(id(plan.get("id")),line.quantity,Math::addExact);lineTotals.merge(line.sku,line.quantity,Math::addExact);}
        Set<String> codes=new HashSet<>();Map<String,List<String>> waybills=new TreeMap<>();Map<String,Long> packageTotals=new TreeMap<>();Map<String,Map<String,Object>> fingerprints=new TreeMap<>();Map<String,List<Map<String,Object>>> oldLines=new HashMap<>();Map<String,WmsProtocol.OutboundPackage> packs=new TreeMap<>();
        for(WmsProtocol.OutboundPackage pack:receipt.packages){Map<String,Object> fingerprint=packageFingerprint(pack);require(codes.add(pack.packageCode),"回传包裹编码重复");waybills.put(db.encode(Arrays.asList(pack.logisticsCode,pack.expressCode)),Arrays.asList(pack.logisticsCode,pack.expressCode));fingerprints.put(pack.packageCode,fingerprint);packs.put(pack.packageCode,pack);((Map<String,Long>)fingerprint.get("items")).forEach((sku,q)->packageTotals.merge(sku,q,Math::addExact));List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_outbound_receipt_package WHERE company_code=? AND task_id=? AND package_code=?",company,taskId,pack.packageCode);if(!old.isEmpty()){if(!hash(fingerprint).equals(old.get(0).get("payload_hash")))throw new WmsOutboundReceiptReviews.Conflict("PACKAGE_CHANGED","已接收包裹的运单或商品数量发生变化");try{oldLines.put(pack.packageCode,db.json.readValue(text(old.get(0).get("lines_json")),List.class));}catch(Exception e){throw new IllegalArgumentException("原包裹来源明细损坏");}}}
        require(lineTotals.equals(packageTotals),"出库商品数量与包裹商品数量不一致");require(!reported.isEmpty()||receipt.complete,"中间出库回传不能为空");if(reported.isEmpty())require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_receipt_package WHERE company_code=? AND task_id=?",Long.class,company,taskId)>0,"尚无实际出库，不能只回传最终状态");
        Map<Long,Long> remaining=new TreeMap<>(reported);for(List<Map<String,Object>> lines:oldLines.values())for(Map<String,Object> line:lines){long key=id(line.get("id")),quantity=id(line.get("quantity"));require(remaining.getOrDefault(key,0L)>=quantity,"累计报文与已接收包裹的来源数量不一致");remaining.put(key,remaining.get(key)-quantity);}
        List<Map<String,Object>> newPackages=new ArrayList<>();Map<Long,Long> delta=new TreeMap<>();for(WmsProtocol.OutboundPackage pack:packs.values()){if(oldLines.containsKey(pack.packageCode))continue;List<Map<String,Object>> assigned=new ArrayList<>();for(Map.Entry<String,Long> item:((Map<String,Long>)fingerprints.get(pack.packageCode).get("items")).entrySet()){long left=item.getValue();for(Map<String,Object> plan:planned.values()){if(!text(plan.get("sku_sn")).equals(item.getKey()))continue;long key=id(plan.get("id")),take=Math.min(left,remaining.getOrDefault(key,0L));if(take==0)continue;assigned.add(map("id",key,"sku_sn",item.getKey(),"quantity",take));remaining.put(key,remaining.get(key)-take);delta.merge(key,take,Math::addExact);left-=take;if(left==0)break;}require(left==0,"包裹数量无法对应回传行和库存批次");}newPackages.add(map("package_code",pack.packageCode,"express_code",pack.expressCode,"warehouse_carrier_code",pack.logisticsCode,"warehouse_carrier_name",pack.logisticsName,"lines",assigned));}require(remaining.values().stream().allMatch(q->q==0),"回传行数量尚未全部归属包裹");
        Map<Long,Long> cumulative=new HashMap<>();for(Map<String,Object> old:db.jdbc.queryForList("SELECT lines_json FROM wms_outbound_receipt_package WHERE company_code=? AND task_id=?",company,taskId))try{for(Map<String,Object> line:(List<Map<String,Object>>)db.json.readValue(text(old.get("lines_json")),List.class))cumulative.merge(id(line.get("id")),id(line.get("quantity")),Math::addExact);}catch(Exception e){throw new IllegalArgumentException("历史出库包裹台账损坏");}for(Map.Entry<Long,Long> item:delta.entrySet())require(cumulative.getOrDefault(item.getKey(),0L)+item.getValue()<=number(planned.get(item.getKey()),"quantity"),"累计出库数量超过原发货行数量");
        // Lock waybill identities in a stable order, including first use, before checking peers.
        for(String key:waybills.keySet()){String logistics=waybills.get(key).get(0),express=waybills.get(key).get(1);db.jdbc.update("INSERT IGNORE INTO wms_outbound_waybill_lock(company_code,logistics_code,express_code) VALUES (?,?,?)",company,logistics,express);db.one("SELECT express_code FROM wms_outbound_waybill_lock WHERE company_code=? AND logistics_code=? AND express_code=? FOR UPDATE",company,logistics,express);}
        boolean conflict=false;
        Set<Long> permitted=new HashSet<>();for(Object value:related)permitted.add(id(value));
        for(Map<String,Object> pack:newPackages){List<Map<String,Object>> peers=db.jdbc.queryForList("SELECT task_id,package_code FROM wms_outbound_receipt_package WHERE company_code=? AND logistics_code=? AND express_code=?",company,text(pack.get("warehouse_carrier_code")),pack.get("express_code"));
            if(peers.stream().anyMatch(peer->id(peer.get("task_id"))!=taskId))conflict=true;
            if(review>0)for(Map<String,Object> peer:peers){long peerShipment=id(db.one("SELECT shipment_id FROM wms_outbound_task WHERE company_code=? AND id=?",company,peer.get("task_id")).get("shipment_id"));require(permitted.contains(peerShipment),"共用运单只能关联同一业务订单的发货单");}
        }
        if(conflict&&review==0)throw new WmsOutboundReceiptReviews.Conflict("WAYBILL_CONFLICT","不同包裹使用了相同快递及运单号");
        if(review>0){require(permitted.contains(id(task.get("shipment_id"))),"核对授权不属于本发货单");for(Map<String,Object> pack:newPackages)pack.put("shared_review_id",review);}
        List<Map<String,Object>> lines=new ArrayList<>();delta.forEach((key,q)->lines.add(map("id",key,"sku_sn",planned.get(key).get("sku_sn"),"batch_code",planned.get(key).get("batch_code"),"quantity",q)));long quantity=delta.values().stream().mapToLong(Long::longValue).sum();Map<String,Object> payload=map("shipment_id",task.get("shipment_id"),"shipment_sn",task.get("shipment_sn"),"task_id",taskId,"original_payload_hash",task.get("payload_hash"),"external_order",receipt.externalOrder,"external_warehouse",receipt.warehouse,"external_owner",receipt.owner,"message_id",receipt.messageId,"final_confirmation",receipt.complete?1:0,"outbound_time",receipt.outboundTime,"warehouse_status",receipt.status,"quantity",quantity,"lines",lines,"packages",newPackages);long event=db.insert("wms_outbound_receipt_event",map("company_code",company,"task_id",taskId,"shipment_sn",receipt.shipmentSn,"message_id",receipt.messageId,"payload_hash",digest,"payload_json",db.encode(payload),"quantity",quantity,"final_confirmation",receipt.complete?1:0));
        for(Map<String,Object> pack:newPackages)db.insert("wms_outbound_receipt_package",map("company_code",company,"task_id",taskId,"event_id",event,"package_code",pack.get("package_code"),"express_code",pack.get("express_code"),"logistics_code",pack.get("warehouse_carrier_code"),"payload_hash",hash(fingerprints.get(pack.get("package_code"))),"lines_json",db.encode(pack.get("lines")),"waybill_slot",QimenProtocol.hash("SHA-256",taskId+"/"+pack.get("package_code"))));db.jdbc.update("UPDATE wms_outbound_task SET dispatch_state='ACCEPTED',external_order=?,warehouse_status=?,last_error='' WHERE company_code=? AND id=?",receipt.externalOrder,receipt.status,company,taskId);return event;
    });if(notifier!=null)notifier.accepted(company,accepted);return accepted;}
    @SuppressWarnings("unchecked") public List<Map<String,Object>> pending(String company,String shipment,boolean includeFailed){List<Object> args=new ArrayList<>();args.add(company);String filter="";if(!shipment.isEmpty()){filter=" AND shipment_sn=?";args.add(shipment);}List<Map<String,Object>> rows=db.jdbc.queryForList("SELECT id,task_id,shipment_sn,payload_json,post_state,post_error FROM wms_outbound_receipt_event WHERE company_code=? AND post_state IN ("+(includeFailed?"'PENDING','FAILED'":"'PENDING'")+")"+filter+" ORDER BY id LIMIT 20",args.toArray());for(Map<String,Object> row:rows)try{row.put("payload",db.json.readValue(text(row.remove("payload_json")),Map.class));}catch(Exception e){throw new IllegalArgumentException("出库回传台账损坏");}return rows;}
    @SuppressWarnings("unchecked") public Map<String,Object> event(String company,long event){Map<String,Object> row=db.one("SELECT id,shipment_sn,payload_json,post_state FROM wms_outbound_receipt_event WHERE company_code=? AND id=?",company,event);try{row.put("payload",db.json.readValue(text(row.remove("payload_json")),Map.class));}catch(Exception e){throw new IllegalArgumentException("出库事件快照损坏");}return row;}
    public Map<String,Object> scanPending(String company){return map("events",pending(company,"",false),"reviews",db.jdbc.queryForList("SELECT shipment_id,shipment_sn FROM wms_outbound_receipt_review WHERE company_code=? AND state='WAIT_REVIEW' ORDER BY id LIMIT 50",company),"review_pending",db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_receipt_review WHERE company_code=? AND state='WAIT_REVIEW'",Long.class,company));}
    public List<Map<String,Object>> reviewSummaries(String company,List<Long> shipments){
        require(shipments!=null&&shipments.size()<=100&&shipments.stream().allMatch(id->id!=null&&id>0),"发货单范围无效，最多100张");
        if(shipments.isEmpty())return Collections.emptyList();
        List<Object> args=new ArrayList<>();args.add(company);args.addAll(shipments);
        return db.jdbc.queryForList("SELECT shipment_id,COUNT(*) pending_count FROM wms_outbound_receipt_review WHERE company_code=? AND state='WAIT_REVIEW' AND shipment_id IN ("+String.join(",",Collections.nCopies(shipments.size(),"?"))+") GROUP BY shipment_id",args.toArray());
    }
    public List<Map<String,Object>> reviews(String company,long shipment){return new WmsOutboundReceiptReviews(db,this).list(company,shipment);}
    public Map<String,Object> review(String company,long shipment,long review,Map<String,Object> body){return new WmsOutboundReceiptReviews(db,this).decide(company,shipment,review,body);}
    public void posted(String company,long event,boolean success,String message){require(message.length()<=1000,"出库记账说明过长");require(db.jdbc.update("UPDATE wms_outbound_receipt_event SET post_state=CASE WHEN post_state='POSTED' THEN post_state ELSE ? END,post_error=CASE WHEN post_state='POSTED' OR ? THEN '' ELSE ? END,posted_at=CASE WHEN ? THEN COALESCE(posted_at,NOW()) ELSE posted_at END WHERE company_code=? AND id=?",success?"POSTED":"FAILED",success,message,success,company,event)==1,"出库回传不存在或不属于当前公司");}
}
